const json=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{"content-type":"application/json; charset=UTF-8","Access-Control-Allow-Origin":"*","Access-Control-Allow-Headers":"Content-Type","Access-Control-Allow-Methods":"GET, POST, PUT, DELETE, OPTIONS"}});

export default {
  async fetch(request, env) {
    const url=new URL(request.url);
    const path=url.pathname;

    if(request.method==="OPTIONS") return new Response(null,{status:204,headers:{"Access-Control-Allow-Origin":"*","Access-Control-Allow-Headers":"Content-Type","Access-Control-Allow-Methods":"GET, POST, PUT, DELETE, OPTIONS"}});

    if(path==="/api/health" && request.method==="GET"){
      try{await env.DB.prepare("SELECT 1").first();return json({ok:true,sistema:"Emirates Parque Flamboyant",banco:"D1 conectado"});}
      catch(e){return json({ok:false,error:"Banco D1 indisponível"},500);}
    }

    if(path==="/api/employees" && request.method==="GET"){const r=await env.DB.prepare("SELECT * FROM employees ORDER BY name COLLATE NOCASE").all();return json(r.results||[]);}
    if(path==="/api/employees" && request.method==="POST"){const b=await request.json();if(!b.name||!b.name.trim())return json({error:"Nome é obrigatório."},400);const r=await env.DB.prepare("INSERT INTO employees (name, role, registration, team, company, status) VALUES (?, ?, ?, ?, ?, ?)").bind(b.name.trim(),b.role||"",b.registration||"",b.team||"",b.company||"TERRAL INCORPORADORA",b.status||"ATIVO").run();return json({ok:true,id:r.meta.last_row_id},201);}

    if(path==="/api/tasks" && request.method==="GET"){const r=await env.DB.prepare("SELECT * FROM tasks WHERE active=1 ORDER BY description COLLATE NOCASE").all();return json(r.results||[]);}
    if(path==="/api/tasks" && request.method==="POST"){const b=await request.json();if(!b.description||!b.unit)return json({error:"Descrição e unidade são obrigatórias."},400);const r=await env.DB.prepare("INSERT INTO tasks (description, unit, unit_value, active) VALUES (?, ?, ?, ?)").bind(b.description.trim(),b.unit.trim(),Number(b.unit_value||0),b.active===false?0:1).run();return json({ok:true,id:r.meta.last_row_id},201);}

    if(path==="/api/time-entries" && request.method==="GET"){const r=await env.DB.prepare("SELECT t.*, e.name AS employee_name FROM time_entries t JOIN employees e ON e.id=t.employee_id ORDER BY t.work_date DESC, e.name COLLATE NOCASE").all();return json(r.results||[]);}
    if(path==="/api/time-entries" && request.method==="POST"){const b=await request.json();if(!b.employee_id||!b.work_date)return json({error:"Funcionário e data são obrigatórios."},400);const r=await env.DB.prepare("INSERT INTO time_entries (employee_id,work_date,entry_time,break_start,break_end,exit_time,normal_hours,overtime_hours,occurrence,notes,launched_by) VALUES (?,?,?,?,?,?,?,?,?,?,?)").bind(Number(b.employee_id),b.work_date,b.entry_time||"",b.break_start||"",b.break_end||"",b.exit_time||"",Number(b.normal_hours||0),Number(b.overtime_hours||0),b.occurrence||"",b.notes||"",b.launched_by||"").run();return json({ok:true,id:r.meta.last_row_id},201);}

    if(path==="/api/production" && request.method==="GET"){const r=await env.DB.prepare("SELECT p.*, e.name AS employee_name, t.description AS task_description, t.unit AS task_unit FROM production_entries p JOIN employees e ON e.id=p.employee_id JOIN tasks t ON t.id=p.task_id ORDER BY p.work_date DESC, e.name COLLATE NOCASE").all();return json(r.results||[]);}
    if(path==="/api/production" && request.method==="POST"){const b=await request.json();if(!b.employee_id||!b.task_id||!b.work_date)return json({error:"Funcionário, tarefa e data são obrigatórios."},400);const q=Number(b.quantity||0),u=Number(b.unit_value||0),t=q*u;const r=await env.DB.prepare("INSERT INTO production_entries (employee_id,task_id,work_date,tower,floor,location,details,quantity,unit_value,total_value,launched_by) VALUES (?,?,?,?,?,?,?,?,?,?,?)").bind(Number(b.employee_id),Number(b.task_id),b.work_date,b.tower||"",b.floor||"",b.location||"",b.details||"",q,u,t,b.launched_by||"").run();return json({ok:true,id:r.meta.last_row_id,total_value:t},201);}

    if(path==="/" && request.method==="GET") return new Response('<!DOCTYPE html>\n<html lang="pt-BR">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Emirates Parque Flamboyant | Terral</title>\n<link rel="icon" type="image/png" href="data:image/png;base64,">\n<style>\n:root{--wine:#65001f;--wine2:#7a092d;--bg:#f4f5f7;--text:#1f2937;--muted:#6b7280;--green:#178642}\n*{box-sizing:border-box}body{margin:0;min-height:100vh;font-family:Arial,Helvetica,sans-serif;background:var(--bg);color:var(--text);display:flex;flex-direction:column}\nheader{background:linear-gradient(115deg,#500018,var(--wine2));color:#fff;padding:24px 32px;display:flex;align-items:center;gap:24px;box-shadow:0 2px 10px #0003}\n.terral{width:170px;max-height:76px;object-fit:contain}.sep{width:1px;height:78px;background:#ffffff66}\n.emirates-box{background:#fff;border-radius:14px;padding:9px 14px;min-width:225px;display:flex;justify-content:center}.emirates{width:200px;max-height:72px;object-fit:contain}\n.project{flex:1}.project h1{margin:0;font-size:27px}.project p{margin:6px 0 0;font-size:16px;opacity:.9}\n.meta{display:flex;gap:24px;font-size:15px;white-space:nowrap}\nmain{width:100%;max-width:1140px;margin:auto;padding:30px 24px;flex:1}\n.panel{background:#fff;border-radius:18px;box-shadow:0 10px 32px rgba(15,23,42,.10);overflow:hidden;border:1px solid #edf0f2}\n.hero{text-align:center;padding:28px 30px 12px}.eyebrow{color:var(--wine);font-size:20px;font-weight:800;margin-bottom:8px}\n.hero h2{font-size:42px;margin:0}.hero p{font-size:21px;color:var(--muted);margin:10px 0 0}\n.status{margin:12px 30px 24px;padding:17px 20px;border-radius:11px;border:1px solid #b8dfc4;background:#eef9f1;display:flex;align-items:center;justify-content:center;gap:12px;font-size:18px}\n.check{width:34px;height:34px;border-radius:50%;background:#25a244;color:#fff;display:grid;place-items:center;font-weight:900}\n#statusText{font-weight:800;color:var(--green)}\n.modules{display:grid;grid-template-columns:1fr 1fr;gap:15px;padding:0 30px 28px}\n.module{border:0;color:#fff;background:linear-gradient(130deg,#500018,#8b1738);border-radius:12px;padding:22px;min-height:132px;display:grid;grid-template-columns:72px 1fr 28px;align-items:center;gap:16px;text-align:left}\n.icon{width:66px;height:66px;border-radius:50%;display:grid;place-items:center;background:#ffffff1f;font-size:31px}\n.module strong{display:block;font-size:21px;margin-bottom:7px}.module small{font-size:15px;line-height:1.45;opacity:.95}.arrow{font-size:30px}\n.panel-foot{border-top:1px solid #e5e7eb;padding:20px 30px;display:flex;justify-content:space-between;gap:20px;font-size:14px}\nfooter{background:linear-gradient(115deg,#500018,#740724);color:#fff;text-align:center;padding:22px;font-size:14px;line-height:1.6}\n@media(max-width:900px){header{flex-wrap:wrap}.meta{width:100%;justify-content:flex-end}.modules{grid-template-columns:1fr}.hero h2{font-size:32px}}\n@media(max-width:650px){header{padding:18px;gap:14px}.terral{width:130px}.sep{display:none}.emirates-box{min-width:0;flex:1}.emirates{width:160px}.project{flex-basis:100%}.meta{justify-content:space-between;font-size:13px}main{padding:18px 12px}.hero h2{font-size:26px}.hero p{font-size:17px}.status{margin:10px 14px 18px}.modules{padding:0 14px 18px}.module{grid-template-columns:58px 1fr 20px;padding:18px}.icon{width:54px;height:54px}.panel-foot{flex-direction:column;padding:16px 18px}}\n</style>\n</head>\n<body>\n<header>\n<img class="terral" src="data:image/png;base64," alt="Terral Incorporadora">\n<div class="sep"></div>\n<div class="emirates-box"><img class="emirates" src="data:image/png;base64," alt="Emirates Parque Flamboyant"></div>\n<div class="sep"></div>\n<div class="project"><h1>EMIRATES PARQUE FLAMBOYANT</h1><p>Controle de Ponto e Produção</p></div>\n<div class="meta"><span>📅 <b id="today"></b></span><span>👤 Administrador</span></div>\n</header>\n\n<main>\n<section class="panel">\n<div class="hero"><div class="eyebrow">BEM-VINDO</div><h2>EMIRATES PARQUE FLAMBOYANT</h2><p>Controle de Ponto e Produção</p></div>\n<div class="status"><div class="check">✓</div><span>Status do sistema: <span id="statusText">VERIFICANDO...</span></span></div>\n<div class="modules">\n<button class="module"><div class="icon">👥</div><div><strong>Funcionários</strong><small>Cadastre e gerencie os funcionários da obra.</small></div><div class="arrow">›</div></button>\n<button class="module"><div class="icon">◷</div><div><strong>Cartão de Ponto</strong><small>Lançamento e consulta do cartão de ponto.</small></div><div class="arrow">›</div></button>\n<button class="module"><div class="icon">⛑</div><div><strong>Produção</strong><small>Lançamento de produção diária da equipe.</small></div><div class="arrow">›</div></button>\n<button class="module"><div class="icon">▤</div><div><strong>Tarefas</strong><small>Cadastre e gerencie as tarefas da obra.</small></div><div class="arrow">›</div></button>\n</div>\n<div class="panel-foot"><span>◉ Banco de dados: <b>emirates-ponto-db (D1)</b></span><span>◷ Última atualização: agora há pouco</span></div>\n</section>\n</main>\n\n<footer>© 2026 Terral Incorporadora. Todos os direitos reservados.<br>Emirates Parque Flamboyant</footer>\n\n<script>\ndocument.getElementById("today").textContent=new Date().toLocaleDateString("pt-BR");\nasync function health(){\n  const el=document.getElementById("statusText");\n  try{\n    const r=await fetch("/api/health"); const d=await r.json();\n    if(!r.ok||!d.ok) throw new Error();\n    el.textContent="ONLINE ✓"; el.style.color="#178642";\n  }catch(e){el.textContent="ERRO";el.style.color="#b42318"}\n}\nhealth();\n</script>\n</body>\n</html>',{headers:{"content-type":"text/html; charset=UTF-8"}});

    return json({error:"Rota não encontrada."},404);
  }
};